CREATE DATABASE IF NOT EXISTS `mikale_club` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `mikale_club`;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `bills`;
DROP TABLE IF EXISTS `order_items`;
DROP TABLE IF EXISTS `orders`;
DROP TABLE IF EXISTS `products`;
DROP TABLE IF EXISTS `categories`;
DROP TABLE IF EXISTS `club_guests`;
DROP TABLE IF EXISTS `club_tables`;
DROP TABLE IF EXISTS `users`;
DROP TABLE IF EXISTS `cache`;
DROP TABLE IF EXISTS `cache_locks`;
DROP TABLE IF EXISTS `jobs`;
DROP TABLE IF EXISTS `job_batches`;
DROP TABLE IF EXISTS `failed_jobs`;
DROP TABLE IF EXISTS `migrations`;

CREATE TABLE `club_tables` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `table_number` varchar(255) NOT NULL UNIQUE,
  `name` varchar(255) NOT NULL,
  `section` varchar(255) NOT NULL DEFAULT 'Main Floor',
  `qr_token` varchar(255) NOT NULL UNIQUE,
  `capacity` int NOT NULL DEFAULT '4',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `club_guests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `guest_code` varchar(255) NOT NULL UNIQUE,
  `name` varchar(255) NOT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `club_table_id` bigint unsigned DEFAULT NULL,
  `status` enum('active','checked_out') NOT NULL DEFAULT 'active',
  `check_in_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `check_out_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `club_guests_club_table_id_foreign` (`club_table_id`),
  CONSTRAINT `club_guests_club_table_id_foreign` FOREIGN KEY (`club_table_id`) REFERENCES `club_tables` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `categories` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL UNIQUE,
  `icon_type` varchar(255) NOT NULL DEFAULT 'cocktail',
  `description` text DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint unsigned NOT NULL,
  `name` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL UNIQUE,
  `sub_title` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `volume_ml` int DEFAULT NULL,
  `alcohol_percentage` decimal(4,1) DEFAULT NULL,
  `taste_notes` varchar(255) DEFAULT NULL,
  `price` decimal(10,2) NOT NULL,
  `original_price` decimal(10,2) DEFAULT NULL,
  `currency` varchar(255) NOT NULL DEFAULT '₺',
  `badge` varchar(255) DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `is_available` tinyint(1) NOT NULL DEFAULT '1',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `products_category_id_foreign` (`category_id`),
  CONSTRAINT `products_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `orders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_number` varchar(255) NOT NULL UNIQUE,
  `club_table_id` bigint unsigned NOT NULL,
  `club_guest_id` bigint unsigned NOT NULL,
  `status` enum('pending','preparing','served','completed','cancelled') NOT NULL DEFAULT 'pending',
  `total_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `guest_note` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `orders_club_table_id_foreign` (`club_table_id`),
  KEY `orders_club_guest_id_foreign` (`club_guest_id`),
  CONSTRAINT `orders_club_table_id_foreign` FOREIGN KEY (`club_table_id`) REFERENCES `club_tables` (`id`) ON DELETE CASCADE,
  CONSTRAINT `orders_club_guest_id_foreign` FOREIGN KEY (`club_guest_id`) REFERENCES `club_guests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `order_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned NOT NULL,
  `quantity` int NOT NULL DEFAULT '1',
  `unit_price` decimal(10,2) NOT NULL,
  `total_price` decimal(10,2) NOT NULL,
  `special_instructions` varchar(255) DEFAULT NULL,
  `status` enum('pending','preparing','served','cancelled') NOT NULL DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `order_items_order_id_foreign` (`order_id`),
  KEY `order_items_product_id_foreign` (`product_id`),
  CONSTRAINT `order_items_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `order_items_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `bills` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `bill_number` varchar(255) NOT NULL UNIQUE,
  `club_guest_id` bigint unsigned NOT NULL,
  `club_table_id` bigint unsigned DEFAULT NULL,
  `subtotal` decimal(10,2) NOT NULL,
  `service_fee` decimal(10,2) NOT NULL DEFAULT '0.00',
  `discount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `total_amount` decimal(10,2) NOT NULL,
  `payment_method` enum('cash','credit_card','vip_account','crypto') NOT NULL DEFAULT 'credit_card',
  `status` enum('unpaid','paid','refunded') NOT NULL DEFAULT 'unpaid',
  `paid_at` timestamp NULL DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `bills_club_guest_id_foreign` (`club_guest_id`),
  KEY `bills_club_table_id_foreign` (`club_table_id`),
  CONSTRAINT `bills_club_guest_id_foreign` FOREIGN KEY (`club_guest_id`) REFERENCES `club_guests` (`id`) ON DELETE CASCADE,
  CONSTRAINT `bills_club_table_id_foreign` FOREIGN KEY (`club_table_id`) REFERENCES `club_tables` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

